import styled from 'styled-components'

type ButtonProps = {
  fullWidth?: boolean // Prop para ocupar todo o container
}

const ButtonContainer = styled.button<ButtonProps>`
  background-color: ${({ theme }) => theme.colors.rosa};
  color: ${({ theme }) => theme.colors.branco};
  border: none;
  padding: 8px 16px;
  font-size: 16px;
  cursor: pointer;
  transition: background-color 0.3s ease;
  width: ${({ fullWidth }) => (fullWidth ? '100%' : 'auto')}; // Lógica para ocupar todo o container
  text-align: center; // Centraliza o texto

  &:hover {
    background-color: ${({ theme }) => theme.colors.rosaEscuro};
  }
`

const ButtonLink = styled(ButtonContainer).attrs({ as: 'a' })`
  text-decoration: none;
  display: inline-block;
`

type Props = {
  type: 'button' | 'link'
  title: string
  to?: string
  onClick?: () => void
  children: string
  fullWidth?: boolean // Nova prop para ocupar todo o container
}

const Button = ({ type, title, to, onClick, children, fullWidth = false }: Props) => {
  if (type === 'button') {
    return (
      <ButtonContainer
        type="button"
        title={title}
        onClick={onClick}
        fullWidth={fullWidth} // Passa a prop fullWidth
      >
        {children}
      </ButtonContainer>
    )
  }
  return (
    <ButtonLink to={to as string} title={title} fullWidth={fullWidth}>
      {children}
    </ButtonLink>
  )
}

export default Button
